'use strict';
const KEY='exs290-evidence-workspace-v1',APP='exs290-evidence-workspace',VERSION=1;
const steps=['Start here','Your question and articles','Details from each study','Compare your studies','Feedback and recommendation','Save and submit'];
const studyFields={population:['Participants & setting','Who actually participated? Include sample size and characteristics that matter to your question.'],intervention:['Intervention or exposure','What did participants do or experience? Include duration, frequency, or dose when relevant.'],comparison:['Comparison','What was it compared with? State “No separate comparison group” when appropriate.'],outcome:['Outcome','What outcome relevant to your question did this study examine? Name the variable, not the result.'],measurement:['How it was measured','What test, instrument, scale, or procedure measured that outcome?'],finding:['Relevant finding','What happened? Preserve the comparison, numbers, units, time point, and uncertainty when reported. Do not invent missing statistics.'],location:['Evidence location','Name the section, table/figure and row, or paragraph; include a page when available. A link alone is not a location.'],qualification:['Important qualification','What population, method, or measurement detail affects comparison with other studies? Explain why.']};
function newSource(i){return {id:'S'+i,link:'',doi:'',authors:'',year:'',title:'',journal:'',volume:'',issue:'',pages:'',type:'',design:'',relevance:'',verified:false,selected:false,included:true,...Object.fromEntries(Object.keys(studyFields).map(k=>[k,'']))};}
function fresh(){return {app:APP,version:VERSION,week:11,step:0,question:'',p:'',i:'',c:'',o:'',setting:'',sources:Array.from({length:6},(_,i)=>newSource(i+1)),current:'S1',studyTab:0,compareFields:['population','intervention','comparison','outcome','measurement','finding','qualification'],compareIds:[],annotations:[],pattern:'',patternIds:[],uncertainty:'',uncertaintyIds:[],overlap:'',overlapLocation:'',overlapImplication:'',synthesis:'',audience:'',recommendation:'',feasibility:'',limits:'',peerConnection:'',peerQuestion:'',peerTakeaway:'',revision:'',exclusions:'',ai:''};}
function clean(x){if(!x||x.app!==APP||x.version!==VERSION||!Array.isArray(x.sources)||x.sources.length<1||x.sources.length>20)throw Error('Choose a compatible Evidence Workspace backup. Current work was kept.');let n=fresh();for(const k of Object.keys(n)){if(typeof n[k]==='string'&&typeof x[k]==='string')n[k]=x[k].slice(0,20000);}n.week=x.week===12?12:11;n.step=Number.isInteger(x.step)?Math.min(5,Math.max(0,x.step)):0;n.studyTab=Number.isInteger(x.studyTab)?Math.min(2,Math.max(0,x.studyTab)):0;n.sources=x.sources.map((s,i)=>{let z=newSource(i+1);for(const k of Object.keys(z))if(typeof z[k]==='string'&&typeof s[k]==='string')z[k]=s[k].slice(0,20000);for(const k of ['verified','selected','included'])if(typeof s[k]==='boolean')z[k]=s[k];z.id='S'+(i+1);return z;});const valid=new Set(n.sources.map(s=>s.id));for(const k of ['compareIds','patternIds','uncertaintyIds'])n[k]=Array.isArray(x[k])?[...new Set(x[k].filter(id=>valid.has(id)))]:[];n.compareFields=Array.isArray(x.compareFields)?x.compareFields.filter(k=>studyFields[k]):n.compareFields;n.annotations=Array.isArray(x.annotations)?x.annotations.filter(a=>a&&['pattern','qualification','question'].includes(a.kind)&&typeof a.note==='string').slice(0,100).map(a=>({kind:a.kind,note:a.note.slice(0,5000),ids:Array.isArray(a.ids)?a.ids.filter(id=>valid.has(id)):[]})):[];if(!valid.has(n.current))n.current=n.sources[0].id;return n;}
let state=fresh(),demo=false,own=null,lookupController=null;
try{let raw=localStorage.getItem(KEY);if(raw)state=clean(JSON.parse(raw));}catch(e){document.getElementById('storageNote').hidden=false;}
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(s){$('toast').textContent=s;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').textContent='',6000);}
function persist(){if(demo){$('saveStatus').textContent='Fictional example · own project kept separately';return;}try{localStorage.setItem(KEY,JSON.stringify(state));$('saveStatus').textContent='Saved in this browser · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}catch(e){$('storageNote').hidden=false;$('saveStatus').textContent='Download a backup to keep work';}}
function src(id=state.current){return state.sources.find(s=>s.id===id)||state.sources[0];}
function authorList(s){return s.authors.split('\n').map(s=>s.trim()).filter(Boolean);}
function authorSurname(a){return a.split(',')[0].trim();}
function cite(s,narrative=false){let a=authorList(s),names=a.map(authorSurname),n=names.length;let who=n===0?(s.title||'Author missing'):n===1?names[0]:n===2?names.join(narrative?' and ':' & '):names[0]+' et al.';return narrative?who+' ('+(s.year||'n.d.')+')':'('+who+', '+(s.year||'n.d.')+')';}
function ref(s){let a=authorList(s);let au=a.length>20?a.slice(0,19).join(', ')+', … '+a.at(-1):a.length>1?a.slice(0,-1).join(', ')+', & '+a.at(-1):a[0]||'[Author missing]';return au+' ('+(s.year||'n.d.')+'). '+(s.title||'[Title missing]')+'. '+(s.journal||'[Journal missing]')+(s.volume?', '+s.volume:'')+(s.issue?'('+s.issue+')':'')+(s.pages?', '+s.pages:'')+'.'+(s.doi?' https://doi.org/'+s.doi:'');}
function refHtml(s){let text=ref(s);let journal=s.journal+(s.volume?', '+s.volume:'');return journal?esc(text).replace(esc(journal),'<em>'+esc(journal)+'</em>'):esc(text);}
function short(s){return s.id+' · '+(s.title?s.title.length>70?s.title.slice(0,70)+'…':s.title:'Untitled source');}
function field(k,label,hint='',opts={}){let value=opts.source?src()[k]:state[k];let attr=opts.source?'data-source="'+k+'"':'data-field="'+k+'"';let id=(opts.source?'s-':'f-')+k;let inp=opts.options?'<select id="'+id+'" '+attr+'><option value="">Choose…</option>'+Object.entries(opts.options).map(([v,t])=>'<option value="'+esc(v)+'" '+(value===v?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select>':opts.text?'<input id="'+id+'" '+attr+' type="text" maxlength="20000" value="'+esc(value)+'">':'<textarea id="'+id+'" '+attr+' maxlength="20000" rows="'+(opts.rows||3)+'">'+esc(value)+'</textarea>';return '<label class="field" for="'+id+'"><span>'+esc(label)+'</span><small class="hint" id="'+id+'-hint">'+esc(hint)+'</small>'+inp.replace(attr,attr+' aria-describedby="'+id+'-hint"')+'</label>';}
function intro(title,text){return '<div class="intro"><p class="kicker">'+(state.week===11?'Week 11 · Organize and compare your articles':'Week 12 · Use feedback and develop your recommendation')+'</p><h2>'+title+'</h2><p>'+text+'</p></div>';}
function choices(key,ids=state.sources.filter(s=>s.selected).map(s=>s.id)){return ids.map(id=>{let s=src(id);return '<label class="sourcechoice"><input type="checkbox" data-list="'+key+'" value="'+id+'" '+(state[key].includes(id)?'checked':'')+'>'+esc(id+' · '+cite(s,true))+'</label>';}).join('')||'<p class="subtle">Select studies in Question & sources first.</p>';}
function start(){return intro('Start or continue your comparison','Choose your week above, then enter your information in the numbered sections. Your entries will build the comparison matrix you’ll use for your project.')+`<section class="panel soft entry-panel"><h3>Ready to work?</h3><p>Begin with your question and article links, or return to the section you were working on. You can move between the tabs without losing your entries.</p><button data-go="1" class="primary">Go to your question and articles</button><p class="subtle">If you want to see what the entries should look like first, use “See a filled-in example” in the toolbar.</p></section><details class="overview-help"><summary>How this work connects to the next two weeks and your final project</summary><p>You’ve spent the last few weeks finding articles and looking closely at individual studies. Comparing them together will help you see where the findings connect, where the studies differ, and what you still need to check before making a recommendation.</p><div class="journey"><div><strong>What you’ll do this week</strong><p>Add the six articles you are considering for your project. Then take a closer look at three of your primary research studies and compare their findings.</p></div><div><strong>How you’ll use this next week</strong><p>Continue working here to complete your comparison, get feedback, and check your interpretation. Use that work to develop your recommendation.</p></div><div><strong>How this connects to your final</strong><p>Your comparison will help you decide what belongs on your poster and prepare you to explain the research in your own words during our meeting.</p></div></div><section class="panel"><h3>Before you start</h3><p>Choose the week you are working on from the menu at the top. Use Week 11 to begin your comparison and Week 12 to continue it, use feedback, and develop your recommendation. Your entries stay in place when you switch weeks.</p><p>Have your research question, articles, previous assignments, and my feedback available. Keep using articles that fit your question. You do not need to start your research over.</p><ol><li>In <strong>Your question and articles</strong>, add your question and article links. Check the citation information against each article.</li><li>In <strong>Details from each study</strong>, use the prompts to record information from three primary studies. You can work on one study at a time.</li><li>In <strong>Compare your studies</strong>, look at that information together and explain what you notice.</li><li>In <strong>Save and submit</strong>, check your work, download your PDF for Canvas, and save a backup so you can continue next week.</li></ol><p class="subtle">You can move between sections and make changes as you go. Use the Week 11 reference if you need an explanation or example.</p></section><section class="panel soft"><h3>What should you be looking for?</h3><p>As you compare your studies, ask yourself: Do their findings point toward a similar answer? Were they studying similar people and measuring the same things? Do any of those differences affect what I can conclude?</p><p>You do not have to find a problem with every study or make the findings agree. Explain what you can support and where you still have questions.</p></section><details><summary>Which articles should I include?</summary><p>For your six articles, include at least four primary research studies, one systematic review, and one additional primary study or systematic review. You will use at least five in your final synthesis, including four primary studies and one systematic review. You may use all six.</p><p>Sources should generally be from the past ten years, with full text available without additional payment, including through the library. Ask me if you need an exception. A narrative review does not meet the systematic-review requirement.</p></details><details><summary>How do I keep my work for next time?</summary><p>Your entries stay in this browser when saving is available. Citation lookup sends only the article identifier to Crossref or Europe PMC; your study notes are not sent for lookup. Download a backup after each session, especially before switching devices or browsers. Use Restore backup to bring those entries into another browser or device.</p><p>The spreadsheet and PDF are copies of your work. Changes you make in those files will not update this workspace. A computer will be easier to use when comparing studies and downloading your files.</p></details></details>`;}

function articleUrl(s){let v=s.link.trim();if(/^10\.\d{4,9}\//i.test(v))v='https://doi.org/'+v;try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function articleAnchor(s){let u=articleUrl(s);return u?'<a class="article-link" href="'+esc(u)+'" target="_blank" rel="noopener">Open original article (new tab)</a>':'<span class="subtle">Add a complete article link to reopen the source.</span>';}
function duplicateWarnings(){let seen=new Map(),out=[];for(let s of state.sources){let doi=(s.doi||s.link.match(/10\.\d{4,9}\/[^\s?#]+/i)?.[0]||'').trim().toLowerCase().replace(/^https?:\/\/(?:dx\.)?doi\.org\//,'').replace(/[.,;]+$/,'');let link=articleUrl(s);if(link){let u=new URL(link);u.hash='';link=u.href.replace(/\/$/,'');}for(let id of [doi?'doi:'+doi:'',link?'url:'+link:''].filter(Boolean)){if(seen.has(id)&&seen.get(id)!==s.id)out.push(s.id+' and '+seen.get(id)+' appear to be the same article. Check that each source is distinct.');else seen.set(id,s.id);}}return [...new Set(out)];}
function reportStudies(){return state.sources.filter(s=>s.selected&&(state.week===11?s.type==='primary':s.included));}
function exportWarnings(){let chosen=new Set(reportStudies().map(s=>s.id));return state.sources.filter(s=>!chosen.has(s.id)&&(state.week===12||s.type==='primary')&&Object.keys(studyFields).some(k=>s[k].trim())).map(s=>s.id+': you entered study details, but this article is not selected for this week’s comparison PDF. Check the article selections or export a draft intentionally.');}
function exportSelection(){let included=reportStudies(),omitted=exportWarnings();return '<div class="panel soft"><h3>Check which studies will appear</h3><p><strong>Comparison PDF:</strong> '+esc(included.map(s=>s.id+' '+cite(s,true)).join('; ')||'No studies selected yet')+'</p><p class="subtle">All article references and links appear in the source list. The spreadsheet keeps every article and all entries.</p>'+omitted.map(t=>'<p class="notice">'+esc(t)+'</p>').join('')+'<button data-go="2">Review article selections</button></div>';}
function question(){let used=state.sources.filter(s=>s.selected).length;return intro('Your research question and articles','Start with your current question and add the articles you are considering. When you read each study, check how closely it fits the people, comparisons, and outcomes in your question.')+'<section class="panel">'+field('question','Your current research question','Use your question from the earlier assignments and make any changes needed based on feedback or your searches.')+'<details><summary>Break your question into PICO elements</summary><p>These describe your question, not a requirement that every study have a separate comparison group.</p><div class="twocol">'+field('p','Population','Who is the question about?',{text:true})+field('i','Intervention or exposure','What action, program, or factor?',{text:true})+field('c','Comparison','Compared with what, if applicable?',{text:true})+field('o','Outcome','What do you want to understand?',{text:true})+'</div></details>'+field('setting','Population or practice setting','Who or what setting could use the answer?',{text:true})+'</section><div class="bar"><h3 style="margin:0">Your articles</h3><span class="progresstext">'+state.sources.filter(s=>s.link&&s.title).length+' articles added · '+used+' chosen for detailed entries</span></div><p class="subtle">This week, add six articles and choose three primary studies to complete in detail. Next week, continue with the articles you will use in your synthesis, including at least four primary studies and one systematic review.</p>'+duplicateWarnings().map(t=>'<p class="notice">'+esc(t)+'</p>').join('')+'<div class="sourcegrid">'+state.sources.map(s=>'<article class="sourcecard '+(s.selected?'active':'')+'"><div class="sourceid">'+s.id+' '+(s.type?'<span class="pill">'+esc(s.type)+'</span>':'')+'</div><h3>'+esc(s.title||'Add an article link')+'</h3><p>'+esc(s.authors?cite(s,true):'Citation details not entered')+'</p><p class="subtle">'+(s.selected?'Completing detailed entries':'Article under consideration')+' · '+(s.verified?'Citation checked':'Citation needs checking')+'</p><button data-edit="'+s.id+'">'+(s.title?'Edit article details':'Add article')+'</button><p style="margin-top:10px">'+articleAnchor(s)+'</p></article>').join('')+'</div><div class="actions"><button data-go="0">← Start here</button><div><button id="addSource">Add another article</button> <button class="primary" data-go="2">Go to study details</button></div></div>';}
function sourcePicker(){return '<label class="field source-select"><span>Choose an article</span><select id="sourcePicker">'+state.sources.map(s=>'<option value="'+s.id+'" '+(s.id===state.current?'selected':'')+'>'+esc(short(s))+'</option>').join('')+'</select></label>';}
function examine(){let s=src();const tabNames=['Article and citation','What the study examined','Findings and things to consider'];let html=intro('Details from each study','Use the prompts below to record the details that matter for your question. You can reuse your own work from earlier assignments. When you are ready, open Compare your studies to see the information together.')+sourcePicker()+'<p>'+articleAnchor(s)+'</p><p class="subtle">The link and citation stay with this article as you move through the sections. Citation lookup fills article details, not the study answers.</p><div class="bar"><label><input type="checkbox" id="selected" '+(s.selected?'checked':'')+'> Complete detailed entries for this article</label><label><input type="checkbox" id="included" '+(s.included?'checked':'')+'> Include this article in my synthesis</label></div><div class="tabs" aria-label="Study entry sections">'+tabNames.map((n,i)=>'<button data-tab="'+i+'" aria-current="'+(state.studyTab===i)+'">'+(i+1)+'. '+n+'</button>').join('')+'</div><section class="panel">';
if(state.studyTab===0)html+='<h3>Start with the article link</h3><div class="inlinerow">'+field('link','Article link or DOI','Keep a stable full-text or library link. DOI or PubMed identifiers support automatic metadata lookup.',{source:true,text:true})+'<button id="lookup" class="primary">Look up citation</button></div><p id="lookupStatus" class="subtle" role="status">Lookup fills available metadata. It does not read, classify, or appraise the article.</p><details open><summary>Check or enter citation details</summary><p>APA draft formatting assumes a journal article. Verify names, title capitalization, journal, year, volume, issue, and pages/article number against the article. Other source types or special cases may need manual correction.</p>'+field('authors','Authors','One author per line: Family name, A. B. Preserve the published author order. For a group author, enter its full name.',{source:true})+'<div class="twocol">'+field('year','Year','Publication year; leave blank only when no date is available.',{source:true,text:true})+field('doi','DOI','Identifier only, for example 10.xxxx/xxxxx. Do not invent one.',{source:true,text:true})+'</div>'+field('title','Article title','Use sentence case; preserve proper nouns and abbreviations.',{source:true,text:true})+field('journal','Journal title','Use the full journal title with its proper capitalization.',{source:true,text:true})+'<div class="threecol">'+field('volume','Volume','If reported.',{source:true,text:true})+field('issue','Issue','If reported.',{source:true,text:true})+field('pages','Pages or article number','Use “Article e123” for an article number.',{source:true,text:true})+'</div></details><div id="citationPreview">'+citationPanel(s)+'</div><label><input type="checkbox" id="verified" '+(s.verified?'checked':'')+'> I checked these citation details against the article.</label><div class="twocol">'+field('type','Source type','Verify from the full article, not its title alone.',{source:true,options:{primary:'Primary study',systematic:'Systematic review',other:'Other / needs checking'}})+field('design','Study design','Examples: randomized trial, cohort, cross-sectional, systematic review with meta-analysis.',{source:true,text:true})+'</div>'+field('relevance','Why this source belongs','Briefly connect it to your question.',{source:true});
if(state.studyTab===1)html+='<h3>Who and what did the study examine?</h3><p class="subtle">For a systematic review, describe the included populations, interventions/exposures, comparisons, and outcomes relevant to your question. Do not treat it as a single primary experiment.</p>'+['population','intervention','comparison','outcome','measurement'].map(k=>field(k,...studyFields[k],{source:true})).join('')+'<details><summary>Outcome versus finding: a fictional example</summary><p><strong>Outcome:</strong> Lower-body strength.<br><strong>Measurement:</strong> One-repetition maximum leg press, in kilograms.<br><strong>Finding:</strong> The difference between groups at eight weeks, with its reported uncertainty. The outcome names what was measured; the finding explains what happened.</p></details>';
if(state.studyTab===2)html+='<h3>What did the study find?</h3>'+['finding','location','qualification'].map(k=>field(k,...studyFields[k],{source:true})).join('')+'<details><summary>If a detail is missing or does not apply</summary><p>Write “Not reported” and explain what you checked when it matters, or “Not applicable” with a reason. “No separate comparison group” is a legitimate description. Do not invent statistics, a comparison, or a safeguard to fill a field.</p></details><p class="inline-note subtle">A study can still be useful when it has limitations. Explain how a particular detail affects your interpretation of the finding.</p>';
return html+'</section><div class="actions"><button data-go="1">← Your sources</button>'+(state.studyTab<2?'<button class="primary" data-tab="'+(state.studyTab+1)+'">Continue with this study</button>':'<button class="primary" data-go="3">Compare your studies</button>')+'</div>';}
function citationPanel(s){return '<div class="panel soft"><h4>APA 7 draft</h4><p class="citation">'+refHtml(s)+'</p><p class="subtle"><strong>Parenthetical:</strong> '+esc(cite(s))+'<br><strong>Narrative:</strong> '+esc(cite(s,true))+'</p><div class="bar"><button data-copy="reference">Copy reference</button><button data-copy="parenthetical">Copy parenthetical</button><button data-copy="narrative">Copy narrative</button></div><p class="subtle">Check the draft. Sources with identical author–year citations may require a/b year suffixes or expanded names; this preview does not resolve those collisions automatically.</p></div>';}
function compare(){let selected=state.sources.filter(s=>s.selected);let ids=state.compareIds.length?state.compareIds:selected.map(s=>s.id).slice(0,3);let cols=ids.map(id=>src(id));return intro('Compare your studies','Choose up to three studies to view beside one another. Read across the rows and look for similarities or differences that affect how you understand the findings.')+'<section class="panel"><h3>Which studies would you like to compare?</h3>'+state.sources.filter(s=>s.selected).map(s=>'<label class="sourcechoice"><input type="checkbox" data-compare="'+s.id+'" '+(ids.includes(s.id)?'checked':'')+'>'+esc(s.id+' · '+cite(s,true))+'</label>').join('')+'<details><summary>Choose which details to show</summary>'+Object.entries(studyFields).map(([k,v])=>'<label class="sourcechoice"><input type="checkbox" data-row="'+k+'" '+(state.compareFields.includes(k)?'checked':'')+'>'+esc(v[0])+'</label>').join('')+'</details></section>'+(cols.length?'<div class="scrolltable" tabindex="0" role="region" aria-label="Evidence comparison table"><table class="comparetable"><thead><tr><th scope="col">Compare</th>'+cols.map(s=>'<th scope="col">'+esc(s.id)+'<br>'+esc(cite(s,true))+'</th>').join('')+'</tr></thead><tbody>'+state.compareFields.map(k=>'<tr><th scope="row">'+esc(studyFields[k][0])+'</th>'+cols.map(s=>'<td>'+esc(s[k]||'Not entered yet')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'<section class="panel"><p>Go to Details from each study and choose the articles you want to compare.</p></section>')+'<section class="panel"><h3>Add a note about what you notice</h3><p class="subtle">Use a note to point out something the displayed studies have in common, a difference that matters, or a question you want to check. Each note will show the articles it refers to.</p><div class="legend"><span class="mark-pattern">Similar findings or details</span><span class="mark-qualification">Qualification</span><span class="mark-question">Something to check</span></div><label class="field"><span>Label</span><select id="annotationKind"><option value="pattern">Similar findings or details</option><option value="qualification">Qualification</option><option value="question">Something to check</option></select></label><label class="field"><span>What do you notice?</span><small class="hint">Name the relevant details. This note will be linked to the studies currently displayed above.</small><textarea id="annotationNote"></textarea></label><button id="addAnnotation">Add note for '+esc(ids.join(', ')||'selected studies')+'</button><div style="margin-top:15px">'+state.annotations.map((a,i)=>'<div class="tagitem mark-'+a.kind+'"><strong>'+esc({pattern:'Similar findings or details',qualification:'Qualification',question:'Something to check'}[a.kind])+' · '+esc(a.ids.join(', '))+'</strong><p>'+esc(a.note)+'</p><button data-delete-note="'+i+'">Remove note</button></div>').join('')+'</div></section><section class="panel"><h3>After looking at the studies together</h3><p class="subtle">Write a brief response to each question below. You are starting to interpret the comparison; you do not need a final recommendation yet.</p><h4>Which studies are you referring to?</h4>'+choices('patternIds')+field('pattern','What do you notice when you compare these studies?','Refer to at least two studies and explain a connection between their findings or other relevant details.')+'<h4>Which studies does your question relate to?</h4>'+choices('uncertaintyIds')+field('uncertainty','What do you still need to understand before making a recommendation?','Explain a difference, missing detail, or uncertainty that affects your interpretation. The studies do not have to disagree.')+'</section><section class="panel"><h3>Does your systematic review include any of these studies?</h3><p class="subtle">Check whether your review includes any of your selected primary studies. If it does, you are seeing the same study in two places, so it should not count as two separate confirmations.</p>'+field('overlap','Which primary studies are included in your review?','List source IDs, state none found, or explain why you cannot determine overlap.')+field('overlapLocation','Where did you check?','Included-study list, study-characteristics table, references, or supplement; include a precise location.',{text:true})+field('overlapImplication','What does that mean for your interpretation?','Explain any overlap, or the uncertainty if available reporting does not allow a conclusion.')+'</section><div class="actions"><button data-go="2">← Examine studies</button><button class="primary" data-go="'+(state.week===11?'5':'4')+'">'+(state.week===11?'Review Week 11 export':'Review & recommend')+' →</button></div>';}
function recommend(){if(state.week===11)return intro('You’ll use this section in Week 12','For now, focus on your article entries and the questions in Compare your studies. You can leave this section for next week.')+'<section class="panel soft"><h3>Keep working in the same project</h3><p>Next week, finish the entries for the articles you will use in your synthesis: at least four primary studies and one systematic review. Then use feedback to check your interpretation and develop a recommendation.</p><p>Peer feedback helps you notice and question your reasoning. It does not certify that the articles are accurate.</p><button class="primary" data-go="5">Export Week 11 progress →</button></section>';
return intro('Use your comparison and feedback','Once your article entries are complete, look at the comparison as a whole. Use feedback to decide what needs checking in the original articles, then explain what you can reasonably recommend and who that recommendation applies to.')+'<section class="panel"><h3>What did the feedback help you notice?</h3><p class="subtle">Record useful peer feedback, or use the same questions for a self-review if feedback is unavailable. Your progress does not depend on a classmate replying.</p>'+field('peerConnection','Connection noticed','What pattern or meaningful difference did the reviewer notice? Identify the sources.')+field('peerQuestion','Clarification needed','What entry or comparison was difficult to interpret?')+field('peerTakeaway','Does the emerging takeaway fit?','Does it extend beyond the populations, outcomes, or settings represented?')+field('revision','What did you verify, keep, or revise?','Name the feedback or self-review question, the source evidence you checked, and your resulting decision. A justified decision to keep an answer counts.')+'</section><section class="panel"><h3>What can you recommend based on these studies?</h3>'+field('synthesis','What does your fuller evidence suggest together?','Connect findings across the sources used in your synthesis. Identify sources with author–year citations. Do not paste separate article summaries.')+field('audience','Who could use this recommendation?','Define the population, practitioner, or practice setting. Your poster addresses a professional/academic viewer; the meeting explains the evidence in everyday language.',{text:true})+field('recommendation','What can you reasonably recommend?','Connect the proposed action or decision to the synthesis. A recommendation can be conditional or explain why evidence is insufficient.')+field('feasibility','Practical fit','Consider resources, time, potential benefits, relevant preferences, and circumstances. Label assumptions rather than inventing client facts.')+field('limits','Conditions and uncertainty','Explain who or what the recommendation applies to and the qualifications that belong beside it.')+field('exclusions','Source decisions, if applicable','If you exclude a candidate, explain why. Replace it if needed to keep at least four primary studies and one systematic review. No rejection is compulsory.')+'</section><div class="actions"><button data-go="3">← Compare & notice</button><button class="primary" data-go="5">Review Week 12 export →</button></div>';}
function missing(){let m=[...duplicateWarnings(),...exportWarnings()];if(!state.question.trim())m.push('Enter your research question.');if(!state.setting.trim())m.push('Identify the population or practice setting.');let candidates=state.sources.filter(s=>s.link.trim()&&s.title.trim());if(candidates.length<6)m.push('Add six articles with their links and titles.');let p=candidates.filter(s=>s.type==='primary').length,r=candidates.filter(s=>s.type==='systematic').length;if(p<4||r<1||p+r<6)m.push('Check your article types: four primary studies, one systematic review, and one additional primary study or systematic review.');for(const s of candidates){if(!s.authors||!s.year||!s.journal||!s.design||!s.relevance)m.push(s.id+': complete citation, design, and relevance details.');if(!s.verified)m.push(s.id+': check and confirm the citation.');}let examined=state.sources.filter(s=>s.selected&&(state.week===11?s.type==='primary':s.included));if(state.week===11&&examined.length<3)m.push('Choose three primary studies and complete their detailed entries.');if(state.week===12&&(examined.filter(s=>s.type==='primary').length<4||examined.filter(s=>s.type==='systematic').length<1))m.push('Examine the sources used in synthesis: at least four primary studies and one systematic review.');for(const s of examined)for(const k of Object.keys(studyFields))if(!s[k].trim())m.push(s.id+': '+studyFields[k][0]+'.');if(!state.pattern||state.patternIds.length<2)m.push('Explain an emerging pattern and select at least two supporting studies.');if(!state.uncertainty||!state.uncertaintyIds.length)m.push('Identify an uncertainty and its relevant studies.');for(const k of ['overlap','overlapLocation','overlapImplication'])if(!state[k])m.push('Complete the systematic-review overlap check.');if(state.week===12)for(const k of ['synthesis','audience','recommendation','feasibility','limits','revision'])if(!state[k])m.push('Complete '+({synthesis:'the connected synthesis',audience:'the recommendation audience',recommendation:'the recommendation',feasibility:'practical fit',limits:'conditions and uncertainty',revision:'the feedback/self-review response'}[k])+'.');if(!state.ai)m.push('Include an AI-use statement.');return [...new Set(m)];}
function textBlock(label,value){return '<p><strong>'+esc(label)+':</strong> '+(value?esc(value):'<span class="empty">Not entered</span>')+'</p>';}
function report(){let examined=reportStudies();return '<section id="report" class="panel report"><p class="kicker">EXS290 · '+(demo?'FICTIONAL EXAMPLE · ':'')+'Week '+state.week+'</p><h2>Connecting the Evidence</h2>'+textBlock('Question',state.question)+textBlock('Population / setting',state.setting)+((state.p||state.i||state.c||state.o)?textBlock('Question PICO',['P: '+state.p,'I: '+state.i,'C: '+state.c,'O: '+state.o].join(' | ')):'')+'<div class="report-section"><h3>Articles for your project</h3>'+state.sources.filter(s=>s.link||s.title).map(s=>'<div class="studyreport"><p><strong>'+s.id+' · '+esc(s.type||'Type not entered')+' · '+esc(s.design)+'</strong></p><p class="citation">'+refHtml(s)+'</p>'+textBlock('Original link',s.link)+textBlock('Relevance',s.relevance)+'<p class="source-details">'+(s.included?'Included in the working synthesis':'Excluded / not currently used')+' · '+(s.verified?'Citation checked':'Citation not confirmed')+'</p></div>').join('')+'</div><div class="report-section"><h3>Evidence comparison</h3><p class="source-details">Studies are grouped for readable printing; the on-screen matrix and spreadsheet provide the side-by-side view.</p>'+examined.map(s=>'<div class="studyreport"><h4>'+esc(s.id+' · '+cite(s,true))+'</h4>'+Object.entries(studyFields).map(([k,v])=>textBlock(v[0],s[k])).join('')+'</div>').join('')+'</div><div class="report-section"><h3>What you noticed and want to check</h3>'+state.annotations.map(a=>textBlock({pattern:'Similar findings or details',qualification:'Qualification',question:'Something to check'}[a.kind]+' ['+a.ids.join(', ')+']',a.note)).join('')+textBlock('Connection between studies ['+state.patternIds.join(', ')+']',state.pattern)+textBlock('Uncertainty ['+state.uncertaintyIds.join(', ')+']',state.uncertainty)+'</div><div class="report-section"><h3>Systematic-review overlap</h3>'+textBlock('Result',state.overlap)+textBlock('Where checked',state.overlapLocation)+textBlock('Implication',state.overlapImplication)+'</div>'+(state.week===12?'<div class="report-section"><h3>Review, verification, and recommendation</h3>'+[['Peer/self-review connection','peerConnection'],['Clarification question','peerQuestion'],['Takeaway check','peerTakeaway'],['Verification and revision','revision'],['Synthesis','synthesis'],['Audience','audience'],['Recommendation','recommendation'],['Practical fit','feasibility'],['Conditions and uncertainty','limits'],['Source decisions','exclusions']].map(([l,k])=>textBlock(l,state[k])).join('')+'</div>':'')+'<div class="report-section"><h3>AI-use statement</h3>'+textBlock('AI use',state.ai)+'</div><p class="source-details">'+(demo?'Fictional instructional example. No real research claims. ':'')+'Exported '+new Date().toLocaleDateString('en-US')+'. This is a progress record, not an automated accuracy assessment.</p></section>';}
function exportView(){return intro('Save your work and submit your PDF','Review your entries below, then download your Week '+state.week+' PDF. The file presents the studies side by side. Check the downloaded file before submitting to Canvas, and keep a backup for next time.')+'<div class="panel soft no-print"><p><strong>Selected week: Week '+state.week+'.</strong> Make sure this matches the Canvas assignment you are submitting. Use the week menu at the top to change it; your entries will stay in place.</p><button id="chooseWeek">Change the selected week</button></div><div class="no-print">'+exportSelection()+'</div><div class="panel no-print">'+field('ai','AI-use statement','State “No AI used,” or identify the help and what you personally verified. You must read and verify the articles and make your own comparisons and interpretations.')+'<button id="check">Check entries for Week '+state.week+'</button><div id="checkResults"></div><div class="actions"><button id="xlsx">Download editable spreadsheet</button><button id="print" class="primary">Download Week '+state.week+' PDF</button></div><p class="subtle" style="margin-top:15px">The spreadsheet is optional for your own sorting and annotations. Edits to it do not sync back here. The JSON backup restores your workspace.</p><details><summary>Exactly what do I submit?</summary><p>For Week 11, submit the PDF with six article records, detailed comparison of three primary studies, your pattern and uncertainty responses, the overlap check, and AI-use statement. For Week 12, update the same project with at least four primary studies and one systematic review in the detailed comparison, your response to feedback or self-review, synthesis, and recommendation.</p><p>For peer review, complete your comparison first and share its PDF through the Canvas discussion. Read the discussion page for the posting and reply dates. After receiving feedback, check the original articles and update your project. If no useful feedback arrives, use the review questions yourself and explain what you checked.</p><ol><li>Check your entries and save a backup.</li><li>Download the weekly PDF. The file includes your comparison, notes, and article list.</li><li>Open the PDF and check readability and completeness.</li><li>Upload it to the Canvas assignment and reopen the submission to confirm the correct file.</li></ol><p>Saving here does not submit to Canvas. If a download is blocked in an embed, save a backup, open the tool in a new tab, and restore it there.</p><p>All student-created text and annotations must be typed. Handwritten text and annotations do not meet submission requirements.</p></details></div>'+report();}
function render(){if(lookupController){lookupController.abort();lookupController=null;}$('week').value=state.week;$('weekhint').textContent=state.week===11?'Add six articles and compare three primary studies this week.':'Continue your comparison and use feedback to develop your recommendation.';$('sampleNote').hidden=!demo;$('nav').innerHTML=steps.map((n,i)=>'<button data-go="'+i+'" '+(state.step===i?'aria-current="step"':'')+'><span>'+String(i+1).padStart(2,'0')+'</span>'+n+'</button>').join('')+'';$('main').innerHTML=[start,question,examine,compare,recommend,exportView][state.step]();}
function move(step){state.step=step;persist();render();$('main').focus();}
function download(blob,name){let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function lookup(){let s=src(),link=s.link.trim();let doi=(link.match(/10\.\d{4,9}\/[^\s?#]+/i)||[])[0];let pmid=link.match(/(?:pubmed\.ncbi\.nlm\.nih\.gov\/|^PMID:\s*)(\d+)/i);if(!doi&&!pmid){$('lookupStatus').textContent='Automatic lookup needs a DOI or PubMed link. Keep your article link and enter the citation details below. Nothing was changed.';return;}doi=doi?doi.replace(/[.,;]+$/,''):doi;let id=s.id;lookupController=new AbortController();$('lookup').disabled=true;$('lookupStatus').textContent='Retrieving article metadata…';try{if(pmid){let r=await fetch('https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=EXT_ID:'+pmid[1]+'%20AND%20SRC:MED&format=json',{signal:lookupController.signal});if(!r.ok)throw Error();let j=await r.json(),v=j.resultList?.result?.[0];if(!v?.doi)throw Error('No DOI available from this PubMed record. Enter the citation details manually.');doi=v.doi;}let r=await fetch('https://api.crossref.org/works/'+encodeURIComponent(doi),{signal:lookupController.signal});if(!r.ok)throw Error();let m=(await r.json()).message;if(src().id!==id)return;let incoming={doi:m.DOI||doi,authors:(m.author||[]).map(a=>a.family?a.family+(a.given?', '+a.given.split(/\s+/).map(p=>p[0]+'.').join(' '):''):(a.name||'')).filter(Boolean).join('\n'),year:String((m.published?.['date-parts']||m['published-print']?.['date-parts']||m['published-online']?.['date-parts']||[[]])[0][0]||''),title:(m.title||[])[0]||'',journal:(m['container-title']||[])[0]||'',volume:m.volume||'',issue:m.issue||'',pages:m.page||(m['article-number']?'Article '+m['article-number']:'')};if((s.title||s.authors)&&!confirm('Replace current citation details with retrieved metadata? Your evidence entries and original link will stay.'))return;Object.assign(s,incoming,{verified:false});lookupController=null;persist();render();$('lookupStatus').textContent='Metadata retrieved from Crossref. Check title capitalization, author names, and article details before confirming. Source type and evidence must be entered by you.';}catch(e){if(e.name!=='AbortError'&&$('lookupStatus'))$('lookupStatus').textContent=e.message&&e.message!=='Failed to fetch'?e.message:'Lookup could not retrieve this source. Your work is kept. Enter or correct citation details manually.';}finally{lookupController=null;if($('lookup'))$('lookup').disabled=false;}}
function makeExample(week=11){let n=fresh();n.week=week;n.question='FICTIONAL EXAMPLE: In inactive adults, how does supervised resistance training compared with usual activity affect strength?';n.p='Inactive adults';n.i='Supervised resistance training';n.c='Usual activity';n.o='Strength';n.setting='Community fitness programs for adults beginning resistance training';n.sources.forEach((s,i)=>{Object.assign(s,{link:'https://example.org/fictional-study-'+(i+1),authors:['Rivera, A.','Chen, B.','Patel, C.','Smith, D.','Jones, E.','Lee, F.'][i],year:String(2020+i),title:'Fictional teaching study '+(i+1)+': supervised exercise and strength',journal:'Fictional Journal of Research Education',volume:'1',issue:'1',pages:String(i+1)+'–'+String(i+3),type:i===4?'systematic':'primary',design:i===4?'Systematic review':'Randomized trial',relevance:'Fictional example examining a strength outcome relevant to the question.',verified:true,selected:i<3,included:true,population:(i===1?'80 adults aged 60–75':'60 adults aged 25–50')+'; inactive volunteers at one center.',intervention:'Supervised resistance training, twice weekly for '+(i===2?'12':'8')+' weeks.',comparison:'Usual activity without the supervised program.',outcome:'Lower-body strength.',measurement:i===2?'Isometric leg strength test, newtons.':'One-repetition maximum leg press, kilograms.',finding:i===2?'FICTIONAL: 40 N higher than comparison after 12 weeks; reported 95% confidence interval 10 to 70 N.':'FICTIONAL: '+(i===1?'8':'12')+' kg higher than comparison after 8 weeks; reported 95% confidence interval '+(i===1?'2 to 14':'4 to 20')+' kg.',location:'Fictional Results, Table 2, lower-body strength row, page 6.',qualification:i===2?'Different measurement units and time point prevent directly comparing numerical magnitudes with S1 and S2.':'Volunteers received supervision; applicability to independent exercise is uncertain.'});});Object.assign(n.sources[4],{population:'FICTIONAL: 12 included trials involving inactive adults aged 25–75 across community and university settings.',intervention:'FICTIONAL: Supervised resistance-training programs lasting 8–16 weeks, with different exercises and schedules.',comparison:'FICTIONAL: Usual activity or no structured resistance-training program in the included trials.',outcome:'Lower-body strength across the included trials.',measurement:'FICTIONAL: Included studies used leg-press maximums and other strength tests; the review compared findings without pooling unlike units.',finding:'FICTIONAL: Most included trials favored supervised training. The review did not provide a single pooled estimate because measures and programs differed.',location:'Fictional review Results, strength outcomes subsection, and included-study table.',qualification:'FICTIONAL: This review includes S1 and S2, so those findings are not independent confirmations. Differences across measures limit direct numerical comparisons.',relevance:'Fictional review offering broader context for supervised resistance training and identifying overlap with the selected primary studies.'});n.compareIds=['S1','S2','S3'];n.patternIds=['S1','S2'];n.uncertaintyIds=['S1','S3'];n.pattern='FICTIONAL: S1 and S2 both show higher leg-press strength than usual activity after eight weeks. They use the same test, which helps comparison, but the age groups differ.';n.uncertainty='FICTIONAL: S3 measures force in newtons at a later time point. Its numerical result cannot be compared directly with the kilograms reported in S1.';n.annotations=[{kind:'pattern',ids:['S1','S2'],note:'Same leg-press outcome and eight-week time point.'},{kind:'qualification',ids:['S1','S3'],note:'Different tests, units, and time points; do not average the numbers.'}];n.overlap='FICTIONAL: Review S5 includes S1 and S2.';n.overlapLocation='Fictional S5, included-study table, rows 1–2.';n.overlapImplication='Do not count S5’s discussion of S1 and S2 as independent confirmations of those results.';n.ai='Fictional instructor-review sample created with AI assistance. No actual study or evidence is represented.';n.synthesis='FICTIONAL: The selected studies suggest a strength benefit in supervised programs, but tests and time points differ. This does not establish the same benefit in independent training.';n.audience='Practitioners planning supervised community programs for inactive adults';n.recommendation='FICTIONAL: Consider a supervised introductory resistance-training program, with individual adaptation and outcome monitoring.';n.feasibility='FICTIONAL: Consider access to equipment, supervision, time, and participant preferences. These are planning considerations, not facts measured in the sample studies.';n.limits='FICTIONAL: Evidence here does not establish long-term adherence or the same benefit without supervision.';n.revision='FICTIONAL self-review: checked S3 measurement and retained separate units rather than combining its result with S1.';if(week===11){for(let s of [n.sources[3],n.sources[5]])for(let k of Object.keys(studyFields))s[k]='';}else{n.sources[3].selected=true;n.sources[4].selected=true;for(let k of Object.keys(studyFields))n.sources[5][k]='';}return n;}
document.addEventListener('input',e=>{let x=e.target;if(x.dataset.field){state[x.dataset.field]=x.value;persist();if(state.step===5)$('report').outerHTML=report();if($('checkResults'))$('checkResults').textContent='Entries changed. Check again before submitting.';}if(x.dataset.source){let s=src();s[x.dataset.source]=x.value;if(['authors','year','title','journal','volume','issue','pages','doi'].includes(x.dataset.source)){s.verified=false;if($('verified'))$('verified').checked=false;if($('citationPreview'))$('citationPreview').innerHTML=citationPanel(s);}persist();}});
document.addEventListener('change',e=>{let x=e.target;if(x.id==='week'){let step=state.step;state.week=Number(x.value);if(demo){state=makeExample(state.week);state.step=step;}persist();render();}if(x.id==='sourcePicker'){state.current=x.value;persist();render();}if(x.dataset.source){src()[x.dataset.source]=x.value;persist();}if(['selected','included','verified'].includes(x.id)){src()[x.id]=x.checked;persist();}if(x.dataset.list){let list=state[x.dataset.list];state[x.dataset.list]=x.checked?[...new Set([...list,x.value])]:list.filter(v=>v!==x.value);persist();}if(x.dataset.compare){let ids=state.compareIds.length?state.compareIds:state.sources.filter(s=>s.selected).slice(0,3).map(s=>s.id);if(x.checked&&ids.length>=3){x.checked=false;notify('Compare up to three at a time. Uncheck one to choose another.');return;}state.compareIds=x.checked?[...ids,x.dataset.compare]:ids.filter(v=>v!==x.dataset.compare);persist();render();}if(x.dataset.row){state.compareFields=x.checked?[...state.compareFields,x.dataset.row]:state.compareFields.filter(v=>v!==x.dataset.row);persist();render();}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.copy){let s=src(),value=b.dataset.copy==='reference'?ref(s):cite(s,b.dataset.copy==='narrative');navigator.clipboard.writeText(value).then(()=>notify('Citation copied as plain text.')).catch(()=>notify('Clipboard unavailable. Select and copy the displayed citation.'));return;}if(b.dataset.go!==undefined)return move(Number(b.dataset.go));if(b.dataset.edit){state.current=b.dataset.edit;state.studyTab=0;return move(2);}if(b.dataset.tab!==undefined){state.studyTab=Number(b.dataset.tab);persist();render();return;}if(b.dataset.deleteNote!==undefined){state.annotations.splice(Number(b.dataset.deleteNote),1);persist();render();return;}switch(b.id){case 'beginWork':move(state.step===0?1:state.step);break;case 'chooseWeek':$('week').scrollIntoView({block:'center'});$('week').focus();break;case 'lookup':lookup();break;case 'addSource':if(state.sources.length>=20){notify('You can keep up to 20 articles in this workspace.');break;}state.sources.push(newSource(state.sources.length+1));persist();render();break;case 'addAnnotation':{let note=$('annotationNote').value.trim(),ids=state.compareIds.length?state.compareIds:state.sources.filter(s=>s.selected).slice(0,3).map(s=>s.id);if(!note||!ids.length){notify('Select studies and write a note first.');break;}state.annotations.push({kind:$('annotationKind').value,note,ids:[...ids]});persist();render();break;}case 'sample':if(!demo){own=JSON.parse(JSON.stringify(state));demo=true;state=makeExample();}persist();render();break;case 'leaveSample':state=own||fresh();demo=false;own=null;persist();render();break;case 'backup':download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'exs290-evidence-workspace'+(demo?'-fictional':'')+'-backup.json');notify('Backup download requested. Check Downloads.');break;case 'restoreBtn':$('restore').click();break;case 'reset':if(confirm('Start a new project in this browser? Download a backup first to keep your current project.')){state=fresh();persist();render();notify(demo?'Fictional example cleared; your own project is still preserved.':'Project cleared.');}break;case 'check':{let m=missing();$('checkResults').innerHTML='<div class="checkresult">'+(m.length?'<strong>Review these entries:</strong><ul>'+m.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'<strong>Required entries are present.</strong><p>Check the articles and your reasoning. This is not an accuracy check or grade.</p>')+'</div>';break;}case 'print':downloadPdf(b);break;case 'xlsx':exportSpreadsheet();notify('Spreadsheet download requested. It does not sync edits back to this workspace.');break;}});
$('restore').addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error('Choose a workspace JSON backup under 3 MB.');let next=clean(JSON.parse(await f.text()));if(!confirm('Replace current entries with this backup? Cancel to save your current work first.'))return;state=next;persist();render();notify('Workspace restored.');}catch(e){notify(e instanceof SyntaxError?'Invalid JSON. Current work was kept.':e.message);}finally{$('restore').value='';}});
function pdfModel(){return {week:state.week,demo,question:state.question,setting:state.setting,pico:[['Population',state.p],['Intervention/exposure',state.i],['Comparison',state.c],['Outcome',state.o]].filter(a=>a[1]).map(a=>a.join(': ')).join(' | '),fields:Object.entries(studyFields).map(([k,v])=>[k,v[0]]),studies:reportStudies().map(s=>({...s,citation:cite(s,true)})),sources:state.sources.filter(s=>s.link||s.title).map(s=>({...s,reference:ref(s)})),notes:[...state.annotations.map(a=>({label:({pattern:'Similar findings or details',qualification:'Qualification',question:'Something to check'})[a.kind]+' ['+a.ids.join(', ')+']',value:a.note})),{label:'Connection between studies ['+state.patternIds.join(', ')+']',value:state.pattern},{label:'Question or uncertainty ['+state.uncertaintyIds.join(', ')+']',value:state.uncertainty}],overlap:[{label:'Which studies overlap?',value:state.overlap},{label:'Where checked',value:state.overlapLocation},{label:'What it means',value:state.overlapImplication}],recommendation:[['Peer/self-review connection','peerConnection'],['Clarification question','peerQuestion'],['Takeaway check','peerTakeaway'],['What I checked, kept, or revised','revision'],['Synthesis','synthesis'],['Audience','audience'],['Recommendation','recommendation'],['Practical fit','feasibility'],['Conditions and uncertainty','limits'],['Source decisions','exclusions']].map(([label,k])=>({label,value:state[k]})),ai:state.ai};}
async function downloadPdf(button){let warnings=missing();if(warnings.length&&!confirm('Some entries need attention. Download a draft anyway? Review Check entries before submitting.'))return;button.disabled=true;try{let bytes=await makeEvidencePdf(pdfModel());download(new Blob([bytes],{type:'application/pdf'}),'exs290-evidence-week-'+state.week+(demo?'-fictional':'')+'.pdf');notify('PDF download requested. Open the file to check it before submitting.');}catch(e){notify('The PDF could not be created. Your entries are kept. Save a backup and try again.');}finally{button.disabled=false;}}
function exportSpreadsheet(){let header=['Source ID','APA reference (plain text)','Parenthetical citation','Narrative citation','Article link','DOI','Source type','Design','Relevance','Citation checked','Examine closely','Use in synthesis',...Object.values(studyFields).map(v=>v[0])];let matrix=[['EXS290 Connecting the Evidence'+(demo?' — FICTIONAL EXAMPLE':'')],['Question',state.question],['Population / setting',state.setting],['P',state.p,'I',state.i,'C',state.c,'O',state.o],[],header,...state.sources.filter(s=>s.link||s.title).map(s=>[s.id,ref(s),cite(s),cite(s,true),s.link,s.doi,s.type,s.design,s.relevance,s.verified?'Yes':'No',s.selected?'Yes':'No',s.included?'Yes':'No',...Object.keys(studyFields).map(k=>s[k])])];let notes=[['Connections and synthesis'],['Entry','Sources','Note'],...state.annotations.map(a=>[a.kind,a.ids.join(', '),a.note]),['Emerging pattern',state.patternIds.join(', '),state.pattern],['Uncertainty',state.uncertaintyIds.join(', '),state.uncertainty],['Overlap','',state.overlap],['Where checked','',state.overlapLocation],['Overlap implication','',state.overlapImplication],...['peerConnection','peerQuestion','peerTakeaway','revision','synthesis','audience','recommendation','feasibility','limits','exclusions','ai'].map(k=>[({peerConnection:'Review connection',peerQuestion:'Clarification question',peerTakeaway:'Takeaway check',revision:'Verification / revision',synthesis:'Synthesis',audience:'Audience',recommendation:'Recommendation',feasibility:'Practical fit',limits:'Conditions / uncertainty',exclusions:'Source decisions',ai:'AI use'})[k],'',state[k]]),[],['Workbook notes','','Editable snapshot. Changes do not sync to the interactive. Source evidence and student interpretation require verification. APA references use plain text here; apply journal/volume italics in final formatting.']];download(new Blob([makeXlsx([{name:'Evidence matrix',rows:matrix,headerRow:6},{name:'Connections',rows:notes,headerRow:2}])],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'exs290-evidence-matrix-week-'+state.week+(demo?'-fictional':'')+'.xlsx');}
render();
